  ${rangeThumbStyle} margin-top: 0px;
  height: ${(props) => props.theme.global.spacing};
  width: ${(props) => props.theme.global.spacing};
  ${(props) => props.focus && props.focusIndicator && focusStyle()}
  ${(props) =>
    props.theme.rangeInput &&
    props.theme.rangeInput.thumb &&
    props.theme.rangeInput.thumb.extend}
`;

/* eslint-disable max-len */
const StyledRangeInput = styled.input`
  box-sizing: border-box;
  position: relative;
  -webkit-appearance: none;
  border-color: transparent;
  height: ${(props) => props.theme.global.spacing};
  width: calc(100% - 16px); /* Adjust width to account for padding */
  padding: 8px; /* Add padding to center the RangeInput */
  cursor: ${(props) => (props.disabled ? 'default' : 'pointer')};
  background: transparent;

  ${(props) =>
    props.theme.rangeInput.pad &&
    edgeStyle(
      'padding',
      props.theme.rangeInput.pad,
      props.responsive,
      props.theme.box.responsiveBreakpoint,
      props.theme,
    )}

  &::-moz-focus-inner {
    border: none;
  }

  &::-moz-focus-outer {
    border: none;
  }

  &::-webkit-slider-runnable-track {
    ${rangeTrackStyle}
  }

  &::-webkit-slider-thumb {
    margin-top: -${(props) => (parseMetricToNum(props.theme.global.spacing) - parseMetricToNum(props.theme.rangeInput.track.height || 0)) * 0.5}px;
    ${rangeThumbStyle}
    ${(props) =>
      !props.disabled &&
      css`
        &:hover {
          ${hoverStyle(props)}
        }
      `}
    ${(props) =>
      props.focus &&
      !props.focusIndicator &&
      css`
        ${hoverStyle(props)}
      `}
  }

  &::-moz-range-track {
    ${rangeTrackStyle}
  }

  &::-moz-range-thumb {
    ${firefoxMicrosoftThumbStyle}
  }

  &::-ms-thumb {
    ${firefoxMicrosoftThumbStyle}
  }

  ${(props) =>
    !props.disabled &&
    css`
      &:hover::-moz-range-thumb {
        ${hoverStyle(props)}
      }

      &:hover::-ms-thumb {
        ${hoverStyle(props)}
      }
    `}

  &::-ms-track {
    ${rangeTrackStyle}
    border-color: transparent;
    color: transparent;
  }

  &::-ms-fill-lower {
    ${(props) => trackColorStyle(props, 'lower')};
    border-color: transparent;
  }

  &::-ms-fill-upper {
    ${(props) => trackColorStyle(props, 'upper')};
    border-color: transparent;
  }

  &:focus::-webkit-slider-thumb {
    ${(props) => props.focus && props.focusIndicator && focusStyle()}
  }

  &:focus-visible {
    outline: 0;
  }
